def extract_cites(s):
    cites = {}
    def add(did, nm):
        nm = strip(nm)
        if did not in cites:
            cites[did] = {"docid": did, "name": nm, "count": 0}
        if nm and not cites[did]["name"]:
            cites[did]["name"] = nm
50→        cites[did]["count"] += 1
    for m in re.finditer(r'data-docid="(\d+)"[^>]*>(.*?)</', s, re.S):
        add(m.group(1), m.group(2))
    for m in re.finditer(r'href="/doc(?:fragment)?/(\d+)/?[^"]*"[^>]*>(.*?)</a>', s, re.S):
        add(m.group(1), m.group(2))
    return cites


